; Jet lost
; $4400-$4415

; Marks the jet as lost: jet_state keeps bit 4 and gets bit 3. When jet Y >= $7f, jet_speed_x and jet_climb become 0.
set_jet_lost
        lda jet_state
        and #$10
        ora #$08
        sta jet_state
        lda SP0Y                        ; Player sprite Y.
        cmp #$7f
        bcc set_jet_lost_done
        lda #$00
        sta jet_speed_x
        sta jet_climb
set_jet_lost_done
        rts
